import{_ as t,o as r,c as a,a6 as o}from"./chunks/framework.BJFjZBwW.js";const u=JSON.parse('{"title":"Broker","description":"","frontmatter":{},"headers":[],"relativePath":"prerequisites/broker.md","filePath":"prerequisites/broker.md","lastUpdated":1785770623000}'),i={name:"prerequisites/broker.md"};function s(l,e,n,h,p,m){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="broker" tabindex="-1">Broker <a class="header-anchor" href="#broker" aria-label="Permalink to &quot;Broker&quot;">​</a></h1><p>The broker will act as an intermediary between OpenMQTTGateway and your <a href="/dev/prerequisites/controller.html">controller</a>, it can be seen as a centralized hub at the heart of your automation system. It carry on messages following a publish / subscribe mechanism.</p><p>All the events or commands could pass by the broker.</p><div class="tip custom-block"><p class="custom-block-title">Recommended setup</p><ul><li><strong>You use Home Assistant</strong>: install the <strong>Mosquitto broker add-on</strong> (Settings → Add-ons → Add-on store), enable the MQTT integration, and create a dedicated user for the gateway. This is the path followed by the <a href="./../getting-started.html">Getting Started guide</a>.</li><li><strong>You don&#39;t</strong>: install <a href="https://mosquitto.org/" target="_blank" rel="noreferrer">Mosquitto</a> on any always-on machine (Raspberry Pi, NAS, server), it is lightweight, open source and well documented.</li></ul></div><p>There are many choices of brokers, here are some of the most popular:</p><ul><li><a href="https://mosquitto.org/" target="_blank" rel="noreferrer">Mosquitto</a> (Open source)</li><li><a href="https://moquette-io.github.io/moquette/" target="_blank" rel="noreferrer">Moquette</a> (Open source)</li><li><a href="https://www.emqx.io/" target="_blank" rel="noreferrer">EMQX</a> (Open Source)</li><li><a href="https://www.hivemq.com/hivemq/features/" target="_blank" rel="noreferrer">HiveMQ</a></li><li>Embedded MQTT brokers (Home Assistant and OpenHAB)</li></ul><p>This <a href="https://en.wikipedia.org/wiki/Comparison_of_MQTT_implementations" target="_blank" rel="noreferrer">wikipedia list</a> gives you more details about the different choices you have. This <a href="https://github.com/mqtt/mqtt.github.io/wiki/libraries" target="_blank" rel="noreferrer">github list</a> seems to be the most exhaustive ones. Here is also some <a href="https://www.hivemq.com/blog/top-10-mqtt-broker-criteria/" target="_blank" rel="noreferrer">ideas of criteria</a> from HiveMQ.</p><p>Once your broker is installed it can be interesting to see the traffic passing to it and to publish data, so as to do that there are several tools available:</p><ul><li><a href="http://mqtt-explorer.com/" target="_blank" rel="noreferrer">MQTT Explorer</a></li><li><a href="https://github.com/hivemq/hivemq-mqtt-web-client" target="_blank" rel="noreferrer">HIVE MQ Web client</a></li><li><a href="https://mqttfx.jensd.de/" target="_blank" rel="noreferrer">MQTT FX</a></li></ul>',9)])])}const c=t(i,[["render",s]]);export{u as __pageData,c as default};
